import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css'; // Import calendar styling
import './AttendancePage.css'; // Import our custom styling
import axios from 'axios';

// Mock Time Tracking data. In a real app, this would be fetched for the selected month.
const mockTimeLogs = {
  '2025-10-01': { status: 'Present', in: '09:05 AM', out: '05:15 PM' },
  '2025-10-02': { status: 'Present', in: '09:10 AM', out: '05:00 PM' },
  '2025-10-03': { status: 'Half Day', in: '09:00 AM', out: '01:00 PM' },
  '2025-10-06': { status: 'On Leave' },
  '2025-10-07': { status: 'Present', in: '08:55 AM', out: '05:05 PM' },
  '2025-10-08': { status: 'Absent' },
  // ... more data for the month
};

const AttendancePage = () => {
  const [date, setDate] = useState(new Date());
  const [selectedDayLog, setSelectedDayLog] = useState(null);

  // This function determines how each day tile in the calendar is styled
  const tileClassName = ({ date, view }) => {
    if (view === 'month') {
      const dateString = date.toISOString().slice(0, 10);
      const log = mockTimeLogs[dateString];
      if (log) {
        return `day-${log.status.toLowerCase().replace(' ', '-')}`;
      }
    }
    return null;
  };

  // This function handles what happens when a user clicks a day
  const onDayClick = (value) => {
    const dateString = value.toISOString().slice(0, 10);
    setSelectedDayLog({ date: dateString, ...mockTimeLogs[dateString] });
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Attendance Calendar</h1>
          <p className="text-sm text-subtext-light">Select a date to view attendance details.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
        {/* Left Column: Calendar */}
        <div className="lg:col-span-2 bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
          <Calendar
            onChange={setDate}
            value={date}
            onClickDay={onDayClick}
            tileClassName={tileClassName}
            className="w-full border-none"
          />
        </div>

        {/* Right Column: Details Panel & Legend */}
        <div className="space-y-8">
          {/* Details for Selected Day */}
          <div className="bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
            <h3 className="text-lg font-semibold text-text-light dark:text-text-dark mb-4">Details for Selected Day</h3>
            {selectedDayLog ? (
              <div className="space-y-2">
                <p><strong>Date:</strong> {selectedDayLog.date}</p>
                <p><strong>Status:</strong> <span className={`font-semibold day-${selectedDayLog.status?.toLowerCase().replace(' ', '-')}`}>{selectedDayLog.status || 'No Record'}</span></p>
                {selectedDayLog.in && <p><strong>Clock In:</strong> {selectedDayLog.in}</p>}
                {selectedDayLog.out && <p><strong>Clock Out:</strong> {selectedDayLog.out}</p>}
              </div>
            ) : (
              <p className="text-subtext-light">Select a day on the calendar to see details.</p>
            )}
          </div>

          {/* Calendar Legend */}
          <div className="bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
            <h3 className="text-lg font-semibold text-text-light dark:text-text-dark mb-4">Legend</h3>
            <ul className="space-y-2 text-sm">
              <li className="flex items-center"><span className="legend-dot day-present"></span> Present</li>
              <li className="flex items-center"><span className="legend-dot day-half-day"></span> Half Day</li>
              <li className="flex items-center"><span className="legend-dot day-on-leave"></span> On Leave</li>
              <li className="flex items-center"><span className="legend-dot day-absent"></span> Absent</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AttendancePage;
